public class CounterService {
    private int sharedCount = 0;
    private final Object lock = new Object();

    // Synchronized method locking on 'this'
    public synchronized void incrementMethod() {
        sharedCount++;
    }

    // Synchronized block locking on a dedicated monitor object
    public void incrementBlock() {
        synchronized (lock) {
            sharedCount++;
            // Demonstrating reentrancy safely within the same thread
            recursiveHelper(3);
        }
    }

    private synchronized void recursiveHelper(int depth) {
        if (depth <= 0) return;
        sharedCount++;
        recursiveHelper(depth - 1);
    }
}
